on conflict (sku) do update set
  name = excluded.name,
  category = excluded.category,
  item_kind = excluded.item_kind,
  description = excluded.description,
  min_stock = excluded.min_stock,
  unit = excluded.unit,
  location = excluded.location,
  brand = excluded.brand,
  model = excluded.model,
  serial_number = excluded.serial_number,
  unit_price = excluded.unit_price,
  supplier = excluded.supplier,
  expiry_date = excluded.expiry_date,
  manufactured_at = excluded.manufactured_at,
  notes = excluded.notes,
  asset_status = excluded.asset_status,
  last_maintenance_date = excluded.last_maintenance_date,
  next_maintenance_date = excluded.next_maintenance_date,
  is_active = excluded.is_active,
  tracks_lot = excluded.tracks_lot,
  tracks_serial = excluded.tracks_serial,
  tracks_expiry = excluded.tracks_expiry,
  max_stock = excluded.max_stock,
  reorder_point = excluded.reorder_point,
  part_number = excluded.part_number,
  manufacturer = excluded.manufacturer,
  subcategory = excluded.subcategory;

insert into public.inventory_items (
  sku,
  name,
  category,
  item_kind,
  description,
  quantity,
  min_stock,
  unit,
  location,
  brand,
  model,
  serial_number,
  unit_price,
  supplier,
  expiry_date,
  manufactured_at,
  notes,
  asset_status,
  last_maintenance_date,
  next_maintenance_date,
  is_active,
  tracks_lot,
  tracks_serial,
  tracks_expiry,
  max_stock,
  reorder_point,
  part_number,
  manufacturer,
  subcategory
